from taf.collectors.ttitrace_snapshot_airphone.collector import TtiTraceSnapshotAirphoneCollector
from taf.collectors.core.templates.dynamic_class_creation import Creating
from taf.collectors.core import NamedComponentFactory
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class TtiTraceSnapshotAirphoneFactory(Creating("tool_executor", "SshExecutor", "executor"),  # type: ignore[misc]
                                      Creating("file_getter", "SshFileGetter", "executor"),  # type: ignore[misc]
                                      NamedComponentFactory):
    """
    factory to create ttitrace snapshot airphone collectors
    """

    def create(self, configuration, existing_arguments):
        """
        Create a ttitrace snapshot airphone collector

        :param dict configuration:
                collection of configuration parameters for the object to be created and other objects,
                that might have to be created as prerequisites
        :param dict existing_arguments:
                existing arguments for the final constructor call, that don't need to be created
                (dict with constructor parameter name as key and argument value as value)

        :return: TtiTraceSnapshotAirphoneCollector
        """
        resulting_arguments = {}
        self._build_arguments(configuration=configuration,
                              existing_arguments=existing_arguments,
                              resulting_arguments=resulting_arguments)
        return TtiTraceSnapshotAirphoneCollector(**resulting_arguments)

    def _build_arguments(self, configuration, existing_arguments, resulting_arguments):
        super(TtiTraceSnapshotAirphoneFactory, self)._build_arguments(
            configuration=configuration,
            existing_arguments=existing_arguments,
            resulting_arguments=resulting_arguments)
        for parameter_name in ["script_path", "log_dir", "target_file_name",
                               "start_timeout", "stop_timeout", "container"]:
            if parameter_name in configuration:
                resulting_arguments[parameter_name] = configuration[parameter_name]
